mapper.select:
select * from b_zhongan_marketing_ban where api_code=#{apiCode} and
  zk_date = #{date} 
order by create_time desc,id desc limit #{limitStart},2000;

select cell,zk_date from b_zhongan_marketing_ban where api_code='${apiCode}' and
(cell='${q.cell}' and zk_date='${q.zkDate}')
group by cell,zk_date;
